def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # Keep the framed template on the left, ending before the all-zero divider.
    split = next((c for c in range(w) if all(grid[r][c] == 0 for r in range(h))), w)
    out = [row[:split] for row in grid]

    # Identify the template compartments between full-background separator rows.
    separators = [r for r in range(h) if all(grid[r][c] == bg for c in range(split))]
    compartments = []
    for a, b in zip(separators, separators[1:]):
        if b > a + 1:
            cells = [(r, c) for r in range(a + 1, b) for c in range(split)
                     if grid[r][c] != bg]
            if cells:
                compartments.append(cells)

    # Find the colored objects to the right of the divider.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(split + 1, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and split < nc < w and
                        (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            minr, maxr = min(x for x, y in cells), max(x for x, y in cells)
            minc, maxc = min(y for x, y in cells), max(y for x, y in cells)
            shape = {(x-minr, y-minc) for x, y in cells}
            objects.append((color, shape))

    def signature(cells):
        minr = min(r for r, c in cells)
        minc = min(c for r, c in cells)
        return {(r-minr, c-minc) for r, c in cells}

    unused = objects[:]
    for cells in compartments:
        sig = signature(cells)
        for i, (color, shape) in enumerate(unused):
            if shape == sig:
                for r, c in cells:
                    out[r][c] = color
                unused.pop(i)
                break
    return out
